-- Regression fixtures are rolled back; no operational records are retained.
begin;
do $$
declare org uuid; tenant uuid; actor uuid; usr uuid; site uuid:=gen_random_uuid();fac uuid:=gen_random_uuid();item uuid:=gen_random_uuid();bin uuid:=gen_random_uuid();team uuid:=gen_random_uuid();receipt uuid:=gen_random_uuid();crate uuid:=gen_random_uuid();work uuid:=gen_random_uuid();shut uuid:=gen_random_uuid();res jsonb;v jsonb;rev int;qty numeric;req uuid;line uuid;po uuid;attempt uuid;blocked boolean;vendor uuid:=gen_random_uuid();entity uuid:=gen_random_uuid();bill uuid:=gen_random_uuid();comp uuid:=gen_random_uuid();blackout uuid:=gen_random_uuid();
begin
 select id,tenant_id into org,tenant from public.organizations where id='c9032ebb-0507-5004-b1ad-0bca7cf3cc53';
 select p.id,u.id into actor,usr from public.people p join auth.users u on lower(u.email)=lower(p.email) where p.tenant_id=tenant limit 1;
 if actor is null then raise exception 'No authenticated club actor available for regression';end if;
 insert into public.sites(id,organization_id,code,name) values(site,org,'VERIFY-'||site,'Rollback equipment verification');
 insert into public.facilities(id,site_id,code,name) values(fac,site,'VERIFY-'||fac,'Rollback equipment verification');
 insert into public.teams(id,organization_id,code,name) values(team,org,'VERIFY-'||team,'Rollback equipment verification');
 perform public.admin_equipment_write(tenant,org,usr,actor,'facilities_equipment_manager','create_item',item,jsonb_build_object('sku','VERIFY-'||item,'name','Rollback test stock','unit','each'),'Rollback-only stock verification');
 perform public.admin_equipment_write(tenant,org,usr,actor,'facilities_equipment_manager','create_bin',bin,jsonb_build_object('facility_id',fac,'code','VERIFY-'||bin,'name','Rollback test bin'),'Rollback-only bin verification');
 v:=jsonb_build_object('item_id',item,'location_id',bin,'quantity',10,'expected',10,'damaged',0,'unit_cost',12.50,'currency','CAD','packing_slip','VERIFY-'||receipt);
 perform public.admin_equipment_write(tenant,org,usr,actor,'facilities_equipment_manager','receive',receipt,v,'Rollback-only receipt verification');
 res:=public.admin_equipment_write(tenant,org,usr,actor,'facilities_equipment_manager','receive',receipt,v,'Rollback-only receipt verification');
 select on_hand into qty from public.inventory_balances where item_id=item and location_id=bin;
 if qty<>10 or res->>'duplicate'<>'true' then raise exception 'Receipt idempotency failed';end if;
 blocked:=false;begin perform public.admin_equipment_write(tenant,org,usr,actor,'facilities_equipment_manager','receive',gen_random_uuid(),v,'Duplicate packing slip test');exception when others then blocked:=true;end;if not blocked then raise exception 'Duplicate slip accepted';end if;
 blocked:=false;begin perform public.admin_equipment_write(tenant,org,usr,actor,'facilities_equipment_manager','receive',gen_random_uuid(),v||jsonb_build_object('location_id',gen_random_uuid(),'packing_slip','different'),'Scope rejection verification');exception when others then blocked:=true;end;if not blocked then raise exception 'Invalid bin accepted';end if;
 v:=jsonb_build_object('team_id',team,'name','Rollback crate','lines',jsonb_build_array(jsonb_build_object('item_id',item,'location_id',bin,'quantity',4)));
 perform public.admin_equipment_write(tenant,org,usr,actor,'facilities_equipment_manager','create_crate',crate,v,'Rollback-only crate verification');
 select reserved into qty from public.inventory_balances where item_id=item and location_id=bin;if qty<>4 then raise exception 'Reservation not applied';end if;
 blocked:=false;begin perform public.admin_equipment_write(tenant,org,usr,actor,'facilities_equipment_manager','create_crate',gen_random_uuid(),jsonb_set(v,'{lines,0,quantity}','20'),'Over-allocation rejection test');exception when others then blocked:=true;end;if not blocked then raise exception 'Stock over-allocated';end if;
 blocked:=false;begin update public.operational_tasks set status='completed' where id=crate;exception when others then if sqlerrm not like '%equipment lifecycle%' then raise;end if;blocked:=true;end;if not blocked then raise exception 'Generic crate completion bypass';end if;
 select revision into rev from public.operational_tasks where id=crate;
 perform public.admin_equipment_write(tenant,org,usr,actor,'facilities_equipment_manager','safety_pass',gen_random_uuid(),jsonb_build_object('id',crate,'revision',rev,'inspected',true),'Physical inspection rollback verification');
 if not exists(select 1 from public.operational_tasks where metadata->>'kind'='equipment_readiness' and metadata->>'crate_id'=crate::text) then raise exception 'Readiness handoff missing';end if;
 select revision into rev from public.operational_tasks where id=crate;
 perform public.admin_equipment_write(tenant,org,usr,actor,'facilities_equipment_manager','return_crate',gen_random_uuid(),jsonb_build_object('id',crate,'revision',rev),'Crate return rollback verification');
 select reserved into qty from public.inventory_balances where item_id=item and location_id=bin;if qty<>0 then raise exception 'Reservation not released';end if;
 perform public.admin_equipment_write(tenant,org,usr,actor,'facilities_equipment_manager','scrap',gen_random_uuid(),jsonb_build_object('item_id',item,'location_id',bin,'quantity',2,'unit_cost',12.50,'currency','CAD','certificate','Rollback-only disposal evidence'),'Disposal rollback verification');
 select on_hand into qty from public.inventory_balances where item_id=item and location_id=bin;if qty<>8 then raise exception 'Disposal did not reduce stock';end if;
 v:=jsonb_build_object('facility_id',fac,'starts_at',now()+interval '1 day','ends_at',now()+interval '2 days');
 perform public.admin_equipment_write(tenant,org,usr,actor,'facilities_equipment_manager','maintenance',work,v,'Maintenance rollback verification');
 insert into public.competitions(id,tenant_id,organization_id,name,venue_facility_id,starts_at,ends_at) values(comp,tenant,org,'Rollback competition',fac,now()+interval '1 day',now()+interval '2 days');
 perform public.admin_equipment_write(tenant,org,usr,actor,'facilities_equipment_manager','shutdown',shut,v,'Emergency closure rollback verification');
 blocked:=false;begin insert into public.competition_seeding_runs(competition_id,run_no,algorithm_code,status) values(comp,1,'verification','draft');exception when others then if sqlerrm not like '%CRITICAL SHUTDOWN RISK%' then raise;end if;blocked:=true;end;if not blocked then raise exception 'Seeding bypassed closure';end if;
 if not exists(select 1 from public.facilities where id=fac and status='UNAVAILABLE') then raise exception 'Shutdown status missing';end if;
 if not exists(select 1 from public.operational_tasks where id=shut and assigned_role='org_admin') then raise exception 'Executive escalation missing';end if;
 blocked:=false;begin perform public.admin_equipment_write(tenant,org,usr,actor,'facilities_equipment_manager','reopen',gen_random_uuid(),jsonb_build_object('id',shut),'Unauthorized reopening verification');exception when others then blocked:=true;end;if not blocked then raise exception 'Crew reopened executive closure';end if;
 perform public.admin_equipment_write(tenant,org,usr,actor,'org_admin','reopen',gen_random_uuid(),jsonb_build_object('id',shut),'Executive reopening rollback verification');
 if not exists(select 1 from public.facilities where id=fac and status='active') then raise exception 'Reopening did not restore status';end if;
 v:=jsonb_build_object('facility_id',fac,'starts_at',now()+interval '5 days','ends_at',now()+interval '6 days');
 perform public.admin_equipment_write(tenant,org,usr,actor,'facilities_equipment_manager','blackout',blackout,v,'Planned holiday blackout verification');
 v:=v||jsonb_build_object('id',blackout,'kind','closure','previous_start',v->>'starts_at','previous_end',v->>'ends_at','starts_at',now()+interval '6 days','ends_at',now()+interval '7 days');
 perform public.admin_equipment_write(tenant,org,usr,actor,'facilities_equipment_manager','reschedule',gen_random_uuid(),v,'Blackout reschedule verification');
 blocked:=false;begin perform public.admin_equipment_write(tenant,org,usr,actor,'facilities_equipment_manager','reschedule',gen_random_uuid(),v,'Stale blackout rejection verification');exception when others then if sqlerrm not like '%Blackout changed%' then raise;end if;blocked:=true;end;if not blocked then raise exception 'Stale blackout update accepted';end if;
 req:=gen_random_uuid();po:=gen_random_uuid();line:=gen_random_uuid();attempt:=gen_random_uuid();
 insert into public.vendors(id,organization_id,tenant_id,vendor_code,name) values(vendor,org,tenant,'VERIFY-'||vendor,'Rollback vendor');
 insert into public.legal_entities(id,organization_id,legal_name) values(entity,org,'Rollback entity');
 insert into public.vendor_bills(id,legal_entity_id,vendor_id,bill_number) values(bill,entity,vendor,'VERIFY-'||bill);
 insert into public.purchase_requests(id,organization_id,purpose) values(req,org,'Rollback-only procurement verification');
 insert into public.purchase_orders(id,purchase_request_id,po_number,status,vendor_id) values(po,req,'VERIFY-'||po,'issued',vendor);
 insert into public.purchase_order_lines(id,purchase_order_id,line_no,item_id,description,quantity,unit_price) values(line,po,1,item,'Rollback test line',5,12.5);
 perform public.admin_equipment_write(tenant,org,usr,actor,'facilities_equipment_manager','receive',attempt,jsonb_build_object('item_id',item,'location_id',bin,'quantity',4,'expected',5,'damaged',1,'unit_cost',12.50,'currency','CAD','packing_slip','VERIFY-'||attempt,'purchase_order_line_id',line),'Vendor mismatch rollback verification');
 if not exists(select 1 from public.purchase_orders where id=po and status='COUNT_MISMATCH_HOLD') then raise exception 'Mismatch hold missing';end if;
 select on_hand into qty from public.inventory_balances where item_id=item and location_id=bin;if qty<>11 then raise exception 'Damaged stock incorrectly received';end if;
 blocked:=false;begin insert into public.ap_payments(vendor_id,vendor_bill_id,amount,payment_date,status) values(vendor,bill,1,current_date,'posted');exception when others then if sqlerrm not like '%COUNT_MISMATCH_HOLD%' then raise;end if;blocked:=true;end;if not blocked then raise exception 'Payment bypassed hold';end if;
 select revision into rev from public.operational_tasks where id=attempt;
 perform public.admin_equipment_write(tenant,org,usr,actor,'treasurer','release_hold',gen_random_uuid(),jsonb_build_object('id',attempt,'revision',rev),'Verified vendor resolution rollback');
 if not exists(select 1 from public.purchase_orders where id=po and status='partially_received') then raise exception 'Hold release failed';end if;
end $$;
rollback;
select 'PASS: receipt replay, duplicate slip, scope, crate reservation, over-allocation, safety handoff, return, disposal, maintenance, closure, executive reopening, discrepancy, release, payment block, seeding lock and generic-completion rejection; planned blackout and stale-window rejection; all fixtures rolled back' as result;
